import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.DYPTBNgj.js";const o="/assets/plugins.CTob_v1b.png",c=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugins.md","filePath":"guide/plugins.md"}'),s={name:"guide/plugins.md"};function l(r,e,d,g,u,h){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>A <a href="./../glossary#plugin">plugin</a> is a node type someone else built and shipped as a single file, install it and it shows up in your node picker right next to the built-ins. This page covers installing, updating, and removing one as a user. Writing your own is a different page: see <a href="./../development/plugin-authoring">Plugin Authoring</a>.</p><p>If you haven&#39;t read <a href="./../getting-started/concepts">Concepts</a> yet, do that first for what a node is.</p><p><img src="'+o+'" alt="The Plugins panel showing an installed plugin and the empty-state canvas"></p><h2 id="opening-plugins" tabindex="-1">Opening Plugins <a class="header-anchor" href="#opening-plugins" aria-label="Permalink to &quot;Opening Plugins&quot;">​</a></h2><p>Click <strong>Plugins</strong> in the sidebar. It&#39;s its own panel, not tucked inside Settings.</p><h2 id="setting-a-plugin-directory" tabindex="-1">Setting a plugin directory <a class="header-anchor" href="#setting-a-plugin-directory" aria-label="Permalink to &quot;Setting a plugin directory&quot;">​</a></h2><p>Before you can install anything, Aerini needs a folder to keep plugin files in. Click <strong>Browse</strong> next to <strong>Plugin directory</strong> and pick or create one. Aerini only accepts a folder chosen this way; the setting cannot be changed from anywhere else. This is a one-time setup step; every plugin you install afterward lives in this same folder, and both <strong>Install .wasm</strong> and drag-and-drop install (below) stay disabled until it&#39;s set.</p><h2 id="installing-a-plugin" tabindex="-1">Installing a plugin <a class="header-anchor" href="#installing-a-plugin" aria-label="Permalink to &quot;Installing a plugin&quot;">​</a></h2><p>Two ways to install a <code>.wasm</code> file (a single node) or an <code>.aerinipkg</code> file (a bundle of more than one node, distributed together):</p><ul><li>Click <strong>Install .wasm</strong> and pick the file from the dialog that opens.</li><li>Drag the file straight onto the Aerini window. Aerini asks you to confirm (&quot;Install plugin &quot;...&quot;? Only install plugins from sources you trust.&quot;) before installing it, the same caution you&#39;d want before running anyone else&#39;s code.</li></ul><p>Either way, Aerini copies the file into your plugin directory (and its signature file, if it has one); each file is written whole or not at all, so a full disk or a closed app never leaves a truncated plugin. If an install is interrupted between the two files, the plugin and its signature file no longer match and Aerini refuses to load it; install it again and reloads the node registry immediately, so the new node is available on the canvas without restarting the app. If installing over an existing plugin with the same identity, Aerini recognizes that and asks whether you want to update it rather than silently overwriting or refusing.</p><p>An <code>.aerinipkg</code> installs as a group: its member nodes appear together under one heading in the installed list, with a single <strong>Remove pack</strong> action instead of removing each node individually. For the same reason a pack&#39;s nodes can&#39;t be replaced or removed one at a time: installing a single <code>.wasm</code> over one of them, or removing one on its own, is refused. Install the newer <code>.aerinipkg</code>, or remove the pack first.</p><h2 id="the-installed-plugins-list" tabindex="-1">The installed plugins list <a class="header-anchor" href="#the-installed-plugins-list" aria-label="Permalink to &quot;The installed plugins list&quot;">​</a></h2><p>Every installed plugin shows its display name, its type ID and filename, and (for a multi-node pack) which pack it belongs to. Two more things show up when relevant:</p><ul><li><strong>A load error</strong>, in place of the type ID/filename line, if Aerini couldn&#39;t actually load the file, an incompatible version, corrupt file, or similar.</li><li><strong>A signature status.</strong> Publishers can optionally sign a plugin. <strong>Unsigned</strong> is the common, expected case for most community plugins and isn&#39;t itself a warning sign. Anything else, verified, unrecognized, or a mismatch, is worth reading; see <a href="./security#the-plugin-wasm-sandbox-boundary">Security §The plugin (.wasm) sandbox boundary</a> for exactly what a signature does and doesn&#39;t guarantee today.</li></ul><h2 id="reloading-and-restarting" tabindex="-1">Reloading and restarting <a class="header-anchor" href="#reloading-and-restarting" aria-label="Permalink to &quot;Reloading and restarting&quot;">​</a></h2><p>Aerini rebuilds the node registry automatically after an install, update, or removal. If a folder&#39;s contents change from outside the app (you copied a file into the plugin directory by hand, say) and the picker doesn&#39;t pick it up, click <strong>Reload Plugins</strong> to force a rebuild. If a reload ever fails on its own, Aerini shows a banner asking you to restart the app to apply the change, a fallback path, not the normal one.</p><h2 id="removing-a-plugin" tabindex="-1">Removing a plugin <a class="header-anchor" href="#removing-a-plugin" aria-label="Permalink to &quot;Removing a plugin&quot;">​</a></h2><p>Click the <strong>×</strong> next to a standalone plugin, or <strong>Remove pack</strong> on a pack&#39;s header to remove every node in it at once. Either takes effect immediately, same as an install.</p><h2 id="what-sandboxing-a-plugin-actually-means" tabindex="-1">What sandboxing a plugin actually means <a class="header-anchor" href="#what-sandboxing-a-plugin-actually-means" aria-label="Permalink to &quot;What sandboxing a plugin actually means&quot;">​</a></h2><p>Every plugin call runs in its own fresh sandbox: no filesystem access at all, a capped memory ceiling, and outbound HTTP filtered by the same rules built-in nodes follow. A plugin node is flagged as a dangerous node in the UI, the same category as Shell Command, Code, and Database, and shows the same confirmation before it runs. That&#39;s a summary; the exact limits, what the sandbox doesn&#39;t protect against, and what a verified signature does and doesn&#39;t mean are covered in full in <a href="./security#the-plugin-wasm-sandbox-boundary">Security</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../development/plugin-authoring">Plugin Authoring</a>, for writing and distributing your own plugin</li><li><a href="./security#the-plugin-wasm-sandbox-boundary">Security</a>, for the full sandbox model and signature verification</li><li><a href="./nodes">Nodes Reference</a>, for how a plugin node looks once it&#39;s on the canvas</li></ul>',24)])])}const f=a(s,[["render",l]]);export{c as __pageData,f as default};
